add_action( 'template_redirect', 'perfectpixel_custom_thank_you_redirect' );

function perfectpixel_custom_thank_you_redirect() {
	$page_id = (int) '{{thank_you_page_id}}';
	if ( ! $page_id || ! function_exists( 'is_wc_endpoint_url' ) || ! is_wc_endpoint_url( 'order-received' ) ) {
		return;
	}
	$order_id = absint( get_query_var( 'order-received' ) );
	$order    = $order_id ? wc_get_order( $order_id ) : false;
	$key      = isset( $_GET['key'] ) ? wc_clean( wp_unslash( $_GET['key'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification

	if ( ! $order || ! hash_equals( $order->get_order_key(), $key ) || $order->has_status( 'failed' ) ) {
		return; // Failed payments keep the default page with the "pay again" options.
	}
	wp_safe_redirect(
		add_query_arg(
			array(
				'order' => $order->get_id(),
				'key'   => $order->get_order_key(),
			),
			get_permalink( $page_id )
		)
	);
	exit;
}
